def _parse_p6_date(value: str) -> date | None:
    if not value:
        return None
    for fmt in ('%Y-%m-%d %H:%M', '%Y-%m-%d'):
        try:
            return datetime.strptime(value[:16], fmt).date()
        except ValueError:
            continue
    return None


def _hours_to_days(hours: str) -> int | None:
    if not hours:
        return None
    try:
        return max(1, round(float(hours) / 8))
    except ValueError:
        return None


